class Solution {
  public int resetTalliesTotalReceipt(int[] readings, int k) {
    int[] a=readings; List<Integer> out=new ArrayList<>();
    {int total=0;for(int x:a){total=x==0?0:total+x;out.add(total);}}
    int answer=0;for(int x:out)answer+=x;return answer;
